        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, p.service_name parent_service, p.span_name parent_span, p.attr_span_kind, p.attr_status_code, p.attr_http_response_status_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-basic-service' AND p.service_name='ts-travel-service' AND p.attr_http_response_status_code=408 GROUP BY ALL", "claim": "Every 408 client span from travel has a basic-service server child with status Unset, so the callee did not fail."},
        {"kind": "log", "sql": "SELECT service_name, level, substr(message,1,200) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level='SEVERE' GROUP BY ALL", "claim": "Travel logs SEVERE HttpClientErrorException 408 Request Timeout, but the response bodies carry success data, about 1050 entries."}
