    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_status_code, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL", "claim": "Route-plan calls to travel-service /trips/left return 500 in 828 calls, with route-plan client p50 near 4.8 s."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_status_code, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' AND c.attr_span_kind='Server' GROUP BY ALL", "claim": "Travel-plan calls to route-plan quickestRoute and cheapestRoute return 500, and travel-plan client spans show 504 timeouts near 60 s."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, c.attr_http_response_status_code code, count(*) n, quantile_cont(c.duration/1e6,0.95) p95ms FROM abnormal_traces c WHERE c.service_name='ts-ui-dashboard' AND c.attr_span_kind='Server' AND c.span_name LIKE '%travelPlan%' OR (c.service_name='ts-ui-dashboard' AND c.span_name LIKE '%trips/left%') GROUP BY ALL", "claim": "UI dashboard server spans for travel-plan and trips/left show 500 errors and p95 latency in seconds."}]},
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_status_code, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-service' AND c.attr_span_kind='Server' GROUP BY ALL", "claim": "UI dashboard calls to travel-service trips/left return 500 in the abnormal period, with error share 1.0 on those calls."}]}
